// Trilha descontraída (marimba, estalos, palmas, baixo saltitante e assobio), WAV 44.1 kHz estéreo.
// 112 BPM. Os compassos são alinhados para que o acorde final caia em "Casa X" (25,40 s no vídeo),
// precedido sempre pelo acorde de Sol (V → I).
// Uso: node scripts/trilha-institucional.mjs <saida.wav>
import fs from 'node:fs';

const SR = 44100;
const DUR = 30;
const N = SR * DUR;
const L = new Float32Array(N);
const R = new Float32Array(N);

const BEAT = 60 / 112;
const BAR = BEAT * 4;
const FINAL = 25.4;
const T0 = FINAL - 11 * BAR; // primeiro compasso da batida (~1,83 s)
const GROOVE = T0 + 2 * BAR; // entram bumbo, baixo e palmas (~6,1 s)
const ASSOBIO = T0 + 5 * BAR; // entra o assobio (~12,5 s)

const hz = (m) => 440 * 2 ** ((m - 69) / 12);
// I – vi – IV – V em Dó maior
const CHORDS = [
	[60, 64, 67], // C
	[57, 60, 64], // Am
	[53, 57, 60], // F
	[55, 59, 62], // G
];
const ROOTS = [36, 33, 41, 43];
const idx = (t) => ((Math.floor((t - T0) / BAR) + 1) % 4 + 4) % 4;

let rng = 4242;
const noise = () => {
	rng = (rng * 1664525 + 1013904223) >>> 0;
	return rng / 2147483648 - 1;
};
const add = (i, v, pan = 0) => {
	if (i < 0 || i >= N) return;
	L[i] += v * (1 - pan);
	R[i] += v * (1 + pan);
};

// marimba: fundamental + parcial 4x com decaimento rápido
const marimba = (start, midi, vel = 1, pan = 0) => {
	const s0 = Math.floor(start * SR);
	const f = hz(midi);
	for (let j = 0; j < SR * 0.6; j++) {
		const t = j / SR;
		const v = (Math.sin(2 * Math.PI * f * t) * Math.exp(-t / 0.22) + 0.35 * Math.sin(2 * Math.PI * f * 4 * t) * Math.exp(-t / 0.03)) * Math.min(1, t / 0.002);
		add(s0 + j, v * vel * 0.14, pan);
	}
};
const baixo = (start, midi, dur, vel = 1) => {
	const s0 = Math.floor(start * SR);
	const f = hz(midi);
	for (let j = 0; j < SR * dur; j++) {
		const t = j / SR;
		const v = (Math.sin(2 * Math.PI * f * t) + 0.3 * Math.sin(4 * Math.PI * f * t) + 0.1 * Math.sin(6 * Math.PI * f * t)) * Math.min(1, t / 0.005) * Math.exp(-t / 0.28);
		add(s0 + j, v * vel * 0.2);
	}
};
const kick = (start, amp = 1) => {
	const s0 = Math.floor(start * SR);
	let ph = 0;
	for (let j = 0; j < SR * 0.25; j++) {
		const tt = j / SR;
		ph += (2 * Math.PI * (50 + 90 * Math.exp(-tt / 0.02))) / SR;
		add(s0 + j, Math.sin(ph) * Math.exp(-tt / 0.1) * amp * 0.4);
	}
};
const palma = (start, amp = 1) => {
	const s0 = Math.floor(start * SR);
	let a = 0, b = 0;
	for (let j = 0; j < SR * 0.18; j++) {
		const tt = j / SR;
		const n = noise();
		a += 0.4 * (n - a);
		b += 0.1 * (a - b);
		const env = (tt < 0.008 ? 0.8 : 0) + (tt > 0.011 && tt < 0.018 ? 0.6 : 0) + Math.exp(-tt / 0.05);
		add(s0 + j, (a - b) * env * amp * 0.3, 0.1);
	}
};
const estalo = (start, amp = 1) => {
	const s0 = Math.floor(start * SR);
	let lp = 0;
	for (let j = 0; j < SR * 0.06; j++) {
		const n = noise();
		lp += 0.7 * (n - lp);
		add(s0 + j, (n - lp) * Math.exp(-(j / SR) / 0.012) * amp * 0.45, -0.3);
	}
};
const shaker = (start, amp = 1) => {
	const s0 = Math.floor(start * SR);
	let lp = 0;
	for (let j = 0; j < SR * 0.06; j++) {
		const n = noise();
		lp += 0.5 * (n - lp);
		const tt = j / SR;
		add(s0 + j, (n - lp) * Math.min(1, tt / 0.008) * Math.exp(-tt / 0.02) * amp * 0.07, 0.4);
	}
};
// assobio: seno com vibrato e ataque suave
const assobio = (start, midi, dur, vel = 1) => {
	const s0 = Math.floor(start * SR);
	const f = hz(midi);
	let ph = 0;
	for (let j = 0; j < SR * dur; j++) {
		const t = j / SR;
		ph += (2 * Math.PI * f * (1 + 0.006 * Math.sin(2 * Math.PI * 5.5 * t))) / SR;
		const env = Math.min(1, t / 0.04) * Math.min(1, (dur - t) / 0.06);
		add(s0 + j, (Math.sin(ph) + 0.02 * noise()) * env * vel * 0.07, 0.15);
	}
};

// ---------- introdução: estalos e marimba subindo ----------
[0.15, 0.6, 1.05, 1.5].forEach((t, i) => marimba(t, [60, 64, 67, 72][i], 0.7, i % 2 ? 0.3 : -0.3));

// ---------- grade principal ----------
// marimba sincopada (posições em tempos dentro do compasso) e baixo saltitante
const RITMO_MARIMBA = [0, 0.75, 1.5, 2, 2.75, 3.5];
const RITMO_BAIXO = [[0, 0], [1.5, 7], [2, 0], [3.5, 7]];
for (let bar = 0; bar < 11; bar++) {
	const t0 = T0 + bar * BAR;
	const c = CHORDS[idx(t0 + 0.01)];
	const r = ROOTS[idx(t0 + 0.01)];
	RITMO_MARIMBA.forEach((p, k) => marimba(t0 + p * BEAT, c[k % 3] + 12, k === 0 ? 0.9 : 0.6, k % 2 ? 0.35 : -0.35));
	for (let b = 0; b < 4; b++) {
		const t = t0 + b * BEAT;
		if (t < GROOVE) {
			if (b === 1 || b === 3) estalo(t);
		} else {
			if (b === 0 || b === 2) kick(t, b === 0 ? 1 : 0.75);
			if (b === 1 || b === 3) palma(t);
		}
		for (let s = 0; s < 4; s++) if (t >= GROOVE) shaker(t + (s * BEAT) / 4, s % 2 ? 1 : 0.5);
	}
	if (t0 >= GROOVE - 0.01) for (const [p, iv] of RITMO_BAIXO) baixo(t0 + p * BEAT, r + 12 + iv, 0.45);
	// assobio: motivo simples sobre as notas do acorde
	if (t0 >= ASSOBIO - 0.01) {
		const top = c.map((m) => m + 12);
		const motivo = bar % 2 === 0
			? [[0, top[1], 0.45], [0.5, top[2], 0.45], [1, top[0] + 12, 0.9], [2.5, top[2], 0.45], [3, top[1], 0.9]]
			: [[0, top[2], 0.9], [1, top[1], 0.45], [1.5, top[0], 0.45], [2, top[1], 1.4]];
		for (const [p, m, d] of motivo) assobio(t0 + p * BEAT, m, d * BEAT);
	}
}

// ---------- final em "Casa X" ----------
[48, 52, 55, 60, 64, 67, 72, 76, 79, 84].forEach((m, i) => marimba(FINAL + i * 0.035, m, 0.9 - i * 0.04, (i % 2) * 0.5 - 0.25));
kick(FINAL, 1.2);
palma(FINAL, 1.1);
baixo(FINAL, 36, 1.5, 1.2);
assobio(FINAL + 0.05, 84, 1.4, 1);
[FINAL + BEAT, FINAL + 2 * BEAT, FINAL + 3 * BEAT].forEach((t, i) => marimba(t, [72, 76, 79][i], 0.5, 0));
marimba(FINAL + 4 * BEAT, 84, 0.7, 0);
marimba(FINAL + 4 * BEAT, 72, 0.6, 0);

// ---------- mixagem ----------
let peak = 0;
for (let i = 0; i < N; i++) peak = Math.max(peak, Math.abs(L[i]), Math.abs(R[i]));
const g = 0.9 / peak;
const buf = Buffer.alloc(44 + N * 4);
buf.write('RIFF', 0); buf.writeUInt32LE(36 + N * 4, 4); buf.write('WAVE', 8);
buf.write('fmt ', 12); buf.writeUInt32LE(16, 16); buf.writeUInt16LE(1, 20); buf.writeUInt16LE(2, 22);
buf.writeUInt32LE(SR, 24); buf.writeUInt32LE(SR * 4, 28); buf.writeUInt16LE(4, 32); buf.writeUInt16LE(16, 34);
buf.write('data', 36); buf.writeUInt32LE(N * 4, 40);
for (let i = 0; i < N; i++) {
	const fade = Math.min(1, (N - i) / (SR * 0.6));
	buf.writeInt16LE(Math.round(Math.tanh(L[i] * g) * fade * 32000), 44 + i * 4);
	buf.writeInt16LE(Math.round(Math.tanh(R[i] * g) * fade * 32000), 46 + i * 4);
}
fs.writeFileSync(process.argv[2] ?? 'trilha.wav', buf);
console.log('trilha descontraída gerada:', DUR, 's');
