	const m = t >= FINAL ? 36 : ROOTS[chordIdx(t)] - 12;
	const tb = t >= FINAL ? t - FINAL : (t - T0) % BAR;
	const env = Math.min(1, tb / 0.02) * (0.6 + 0.4 * Math.exp(-tb / 0.5)) * (t >= FINAL ? Math.exp(-(t - FINAL) / 1.2) : 1);
