const kick = (start, amp) => {
	const s0 = Math.floor(start * SR);
	let ph = 0;
	for (let j = 0; j < SR * 0.3; j++) {
		const tt = j / SR;
		ph += (2 * Math.PI * (45 + 70 * Math.exp(-tt / 0.025))) / SR;
		add(s0 + j, Math.sin(ph) * Math.exp(-tt / 0.14) * amp * 0.45);
	}
};
